//! Field maps between the units' structs and the DGROUP image (Stage A of
//! docs/arch/60-engine-assembly.md, section 4.3). GENERATED by
//! `python -P tools/port/state_inventory.py` from the `DG:` comments and address tables
//! of src/*.zig: do not edit, re-run the tool.
//!
//! One entry per field, or per address of a field whose comment names several: the
//! field, the first element and the number of elements it covers (the field flattened
//! to its element type), the DGROUP address of the first, and the original's size of one
//! element in bytes. The count is the unit's own declared length, or the `dg_fields`
//! length where the unit gives one. `src/dgroup.zig` binds a map to its struct and
//! checks at compile time that every field exists with that element size.

pub const Entry = struct { field: []const u8, first: usize, count: usize, addr: u16, esize: usize };

